(function(root){
 const defaults=()=>({mode:'score',hour24:false,duration:300000,remaining:300000,deadline:null,sound:false,courts:[{name:'COURT 01',teams:[{name:'HOME',score:0,sets:0},{name:'AWAY',score:0,sets:0}],serve:0},{name:'COURT 02',teams:[{name:'HOME',score:0,sets:0},{name:'AWAY',score:0,sets:0}],serve:0}]});
 const remaining=(s,now=Date.now())=>s.deadline===null?s.remaining:Math.max(0,s.deadline-now);
 const format=ms=>{const sec=Math.ceil(Math.max(0,ms)/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`};
 function normalize(raw){const s=defaults();if(!raw||typeof raw!=='object')return s;if(['clock','timer','score','dual'].includes(raw.mode))s.mode=raw.mode;s.hour24=raw.hour24===true;s.sound=raw.sound===true;for(const k of ['duration','remaining'])if(Number.isFinite(raw[k])&&raw[k]>=0&&raw[k]<=5999000)s[k]=raw[k];if(Number.isFinite(raw.deadline)&&raw.deadline>0)s.deadline=raw.deadline;if(Array.isArray(raw.courts))raw.courts.slice(0,2).forEach((c,i)=>{if(!c)return;s.courts[i].name=String(c.name||s.courts[i].name).slice(0,30);s.courts[i].serve=c.serve===1?1:0;if(Array.isArray(c.teams))c.teams.slice(0,2).forEach((t,j)=>{if(!t)return;const team=s.courts[i].teams[j];team.name=String(t.name||team.name).slice(0,24);for(const k of ['score','sets'])if(Number.isInteger(t[k]))team[k]=Math.max(0,Math.min(k==='score'?999:99,t[k]));});});return s;}
 const api={defaults,remaining,format,normalize};if(typeof module!=='undefined')module.exports=api;else root.GymModel=api;
})(typeof window!=='undefined'?window:globalThis);
